import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def speaker_pairs(ctx):
    inputs = torch.randn(2, generator=ctx.rng.torch)
    positive = torch.tensor([1.0, 0.0])
    negatives = torch.tensor([[0.0, 1.0]])
    negative_mask = torch.tensor([False])
    return {"inputs": synth.Tensor(inputs), "positive": synth.Tensor(positive), "negatives": synth.Tensor(negatives), "negative_mask": synth.Tensor(negative_mask)}
dataset = synth.Spec("falcon-speaker-pairs", generator=speaker_pairs, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class SpeakerEncoder(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=2, out_features=2)
    def forward(self, inputs):
        return {"query": self.network(inputs)}
trainer = Trainer(SpeakerEncoder(), train, recipe="structured-objective", recipe_config={"loss": "falcon-speaker-contrastive-loss", "loss_kwargs": {"margin": 0.5, "tau": 1.0}, "bindings": {"logits_or_prediction": {"output": "query"}, "targets": {"batch": "positive"}, "negatives": {"batch": "negatives"}, "negative_mask": {"batch": "negative_mask"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
